// Scratch probe: one ACP agent process, several sessions, one short turn each.
// Measures the per-session prompt size with and without Claude Code's built-in tools.
import { spawn } from 'node:child_process';
import { Readable, Writable } from 'node:stream';
import { ClientSideConnection, ndJsonStream, PROTOCOL_VERSION, type Client } from '@agentclientprotocol/sdk';

const env = { ...process.env };
delete env.CLAUDECODE; delete env.CLAUDE_CODE_ENTRYPOINT; delete env.CLAUDE_CODE_SSE_PORT;
const child = spawn('../scripts/claude-ollama.sh --acp', { shell: true, stdio: ['pipe', 'pipe', 'inherit'], env });

let text = '';
const client: Client = {
  sessionUpdate: async (p) => { const u = p.update; if (u.sessionUpdate === 'agent_message_chunk' && u.content.type === 'text') text += u.content.text; },
  requestPermission: async (p) => { const r = p.options.find((o) => o.kind?.startsWith('reject')); return r ? { outcome: { outcome: 'selected', optionId: r.optionId } } : { outcome: { outcome: 'cancelled' } }; },
  readTextFile: async () => { throw new Error('off'); },
  writeTextFile: async () => { throw new Error('off'); },
};
const conn = new ClientSideConnection(() => client,
  ndJsonStream(Writable.toWeb(child.stdin!) as WritableStream<Uint8Array>, Readable.toWeb(child.stdout!) as ReadableStream<Uint8Array>));

async function turn(label: string, meta?: Record<string, unknown>) {
  const t0 = Date.now();
  const s = await conn.newSession({ cwd: process.cwd(), mcpServers: [], ...(meta ? { _meta: meta } : {}) });
  text = '';
  await conn.prompt({ sessionId: s.sessionId, prompt: [{ type: 'text', text: 'Reply with exactly: ok' }] });
  console.log(`${new Date().toISOString()}  ${label.padEnd(22)} ${((Date.now() - t0) / 1000).toFixed(1)}s  reply=${JSON.stringify(text.slice(0, 40))}`);
}

await conn.initialize({ protocolVersion: PROTOCOL_VERSION, clientCapabilities: { fs: { readTextFile: false, writeTextFile: false }, terminal: false }, clientInfo: { name: 'probe', version: '0' } });
await turn('A tools default');
await turn('B tools []', { claudeCode: { options: { tools: [] } } });
await turn('C tools [] (2nd sess)', { claudeCode: { options: { tools: [] } } });
child.kill('SIGKILL');
process.exit(0);

