// Replay the agent judge's real inputs from a finished run, tools on vs tools off.
//
// Rebuilds each test's judge prompt with AgentJudge's own buildPrompt from the run's
// artifacts (per-test JSON + container log) and the testcase YAML at the run's commit,
// checks it against the "Prompt size" the run logged, then judges every prompt in a
// FRESH session twice — Claude Code's default tools, and tools: [] — so the only
// variable is the tool set, not conversation growth.
//
//   npx tsx replay-judge.ts <artifact-dir> <yaml-dir> <expected-sizes.txt> [--dry]
import { readFileSync, writeFileSync } from 'node:fs';
import { spawn } from 'node:child_process';
import { Readable, Writable } from 'node:stream';
import yaml from 'js-yaml';
import { ClientSideConnection, ndJsonStream, PROTOCOL_VERSION, type Client } from '@agentclientprotocol/sdk';
import { AgentJudge } from './src/judge/agent-judge.js';
import { extractJson } from './src/judge/extract-json.js';

const [artDir, yamlDir, sizesFile] = process.argv.slice(2);
const dry = process.argv.includes('--dry');

// ---- 1. rebuild the exact judge inputs --------------------------------------------
const expected = readFileSync(sizesFile, 'utf8').trim().split('\n').map((l) => l.split(' '));
