1	// Replay the agent judge's real inputs from a finished run, tools on vs tools off.
2	//
3	// Rebuilds each test's judge prompt with AgentJudge's own buildPrompt from the run's
4	// artifacts (per-test JSON + container log) and the testcase YAML at the run's commit,
5	// checks it against the "Prompt size" the run logged, then judges every prompt in a
6	// FRESH session twice — Claude Code's default tools, and tools: [] — so the only
7	// variable is the tool set, not conversation growth.
8	//
9	//   npx tsx replay-judge.ts <artifact-dir> <yaml-dir> <expected-sizes.txt> [--dry]
10	import { readFileSync, writeFileSync } from 'node:fs';
11	import { spawn } from 'node:child_process';
12	import { Readable, Writable } from 'node:stream';
13	import yaml from 'js-yaml';
14	import { ClientSideConnection, ndJsonStream, PROTOCOL_VERSION, type Client } from '@agentclientprotocol/sdk';
15	import { AgentJudge } from './src/judge/agent-judge.js';
16	import { extractJson } from './src/judge/extract-json.js';
17	
18	const [artDir, yamlDir, sizesFile] = process.argv.slice(2);
19	const dry = process.argv.includes('--dry');
20	const only = process.env.REPLAY_ONLY?.split(',');           // e.g. TC-MODELS-001,TC-MODELS-016
21	const arms = (process.env.REPLAY_ARMS ?? 'on,off').split(','); // which tool configurations to run
22	
23	// ---- 1. rebuild the exact judge inputs --------------------------------------------
24	const expected = readFileSync(sizesFile, 'utf8').trim().split('\n').map((l) => l.split(' '));
25	const judge = new AgentJudge() as unknown as { buildPrompt(r: unknown): string };
26	const cases: { id: string; prompt: string; original: boolean }[] = [];
27	let exact = 0;
28	for (const [id, size] of expected.filter(([id]) => !only || only.includes(id))) {
29	  const res = JSON.parse(readFileSync(`${artDir}/${id}.json`, 'utf8'));
30	  const result = {
31	    testCase: yaml.load(readFileSync(`${yamlDir}/${id}.yml`, 'utf8')),
32	    steps: res.steps,
33	    logs: readFileSync(`${artDir}/${id}.log`, 'utf8'),
34	    totalDuration: res.duration,
35	  };
36	  const prompt = judge.buildPrompt(result);
37	  const ok = prompt.length === Number(size);
38	  exact += ok ? 1 : 0;
39	  if (!ok) console.log(`  size mismatch ${id}: rebuilt ${prompt.length}, run logged ${size}`);
40	  cases.push({ id, prompt, original: res.agentJudge.pass });
41	}
42	console.log(`fidelity: ${exact}/${cases.length} prompts rebuilt byte-count-exact`);
43	if (dry) process.exit(0);
44	
45	// ---- 2. one agent process, a fresh session per judgement ---------------------------
46	const env = { ...process.env };
47	delete env.CLAUDECODE; delete env.CLAUDE_CODE_ENTRYPOINT; delete env.CLAUDE_CODE_SSE_PORT;
48	const child = spawn('../scripts/claude-ollama.sh --acp', { shell: true, stdio: ['pipe', 'pipe', 'inherit'], env });
49	let text = '';
50	const client: Client = {
51	  sessionUpdate: async (p) => { const u = p.update; if (u.sessionUpdate === 'agent_message_chunk' && u.content.type === 'text') text += u.content.text; },
52	  requestPermission: async (p) => { toolAsks++; const r = p.options.find((o) => o.kind?.startsWith('reject')); return r ? { outcome: { outcome: 'selected', optionId: r.optionId } } : { outcome: { outcome: 'cancelled' } }; },
53	  readTextFile: async () => { throw new Error('off'); },
54	  writeTextFile: async () => { throw new Error('off'); },
55	};
56	let toolAsks = 0;
57	const conn = new ClientSideConnection(() => client,
58	  ndJsonStream(Writable.toWeb(child.stdin!) as WritableStream<Uint8Array>, Readable.toWeb(child.stdout!) as ReadableStream<Uint8Array>));
59	await conn.initialize({ protocolVersion: PROTOCOL_VERSION, clientCapabilities: { fs: { readTextFile: false, writeTextFile: false }, terminal: false }, clientInfo: { name: 'replay', version: '0' } });
60	
61	async function judgeOnce(prompt: string, toolsOff: boolean) {
62	  const t0 = Date.now();
63	  const s = await conn.newSession({ cwd: process.cwd(), mcpServers: [], ...(toolsOff ? { _meta: { claudeCode: { options: { tools: [] } } } } : {}) });
64	  text = ''; toolAsks = 0;
65	  await conn.prompt({ sessionId: s.sessionId, prompt: [{ type: 'text', text: prompt }] });
66	  const json = extractJson(text);
67	  let pass: boolean | null = null, reason = '';
68	  try { const j = JSON.parse(json ?? ''); pass = typeof j.pass === 'string' ? j.pass === 'true' : j.pass; reason = j.reason ?? ''; } catch { reason = `unparsed: ${text.slice(0, 80)}`; }
69	  return { pass, reason, secs: (Date.now() - t0) / 1000, toolAsks };
70	}
71	
72	await judgeOnce('Reply with exactly: ok', true); // warm the model so neither arm pays the load
73	
74	const rows: unknown[] = [];
75	for (const c of cases) {
76	  const skip = { pass: null, reason: 'skipped', secs: 0, toolAsks: 0 };
77	  const on = arms.includes('on') ? await judgeOnce(c.prompt, false) : skip;
78	  const off = arms.includes('off') ? await judgeOnce(c.prompt, true) : skip;
79	  rows.push({ id: c.id, original: c.original, on, off });
80	  console.log(`${c.id}  run=${c.original ? 'PASS' : 'FAIL'}  tools-on=${on.pass ? 'PASS' : 'FAIL'} ${on.secs.toFixed(1)}s asks=${on.toolAsks}  tools-off=${off.pass ? 'PASS' : 'FAIL'} ${off.secs.toFixed(1)}s asks=${off.toolAsks}`);
81	}
82	writeFileSync('replay-out.json', JSON.stringify(rows, null, 2));
83	child.kill('SIGKILL');
84	process.exit(0);

