// Labeled judge cases: does the agent judge know a broken reply when it sees one?
//
// Each case takes a real judge input from a finished run and changes ONLY the reply a
// step printed (plus done_reason / eval_count where the case needs it). The prompt is
// then rebuilt with AgentJudge's own buildPrompt and judged in a fresh session.
//
//   npx tsx judge-cases.ts <artifact-dir> <yaml-dir>
//   env: TRIALS_OFF (default 3), TRIALS_ON (default 1)
import { readFileSync, writeFileSync } from 'node:fs';
import { spawn } from 'node:child_process';
import { Readable, Writable } from 'node:stream';
import yaml from 'js-yaml';
import { ClientSideConnection, ndJsonStream, PROTOCOL_VERSION, type Client } from '@agentclientprotocol/sdk';
import { AgentJudge } from './src/judge/agent-judge.js';
import { extractJson } from './src/judge/extract-json.js';

const [artDir, yamlDir] = process.argv.slice(2);
const TRIALS_OFF = Number(process.env.TRIALS_OFF ?? 3);
const TRIALS_ON = Number(process.env.TRIALS_ON ?? 1);
const PICK = process.env.CASES?.split(',').map(Number); // run only these case numbers
const OUT = process.env.OUT ?? 'judge-cases-out.json';

type Base = { id: string; step: string; label: 'response' | 'content' };
const BASES: Record<string, Base> = {
  text: { id: 'TC-MODELS-008', step: 'Test inference', label: 'response' },   // gemma3:270m
  thinking: { id: 'TC-MODELS-003', step: 'Test inference', label: 'response' }, // deepseek-r1:1.5b
  vision: { id: 'TC-MODELS-016', step: 'Vision inference', label: 'content' },  // gemma4:12b
};
const loop = (unit: string) => unit.repeat(Math.ceil(400 / unit.length)).slice(0, 400);

type Case = { n: number; base: keyof typeof BASES; what: string; reply: string; done_reason: string; eval_count: number; expect: boolean };
const CASES: Case[] = [
  { n: 1, base: 'text', what: 'control, correct', reply: '2 + 2 equals 4.', done_reason: 'stop', eval_count: 8, expect: true },
  { n: 2, base: 'text', what: 'wrong but readable', reply: '2 + 2 equals 5.', done_reason: 'stop', eval_count: 8, expect: true },
  { n: 3, base: 'text', what: 'terse, ignored instruction', reply: '4', done_reason: 'stop', eval_count: 2, expect: true },
  { n: 4, base: 'vision', what: 'wrong shape named', reply: 'arc', done_reason: 'stop', eval_count: 6, expect: true },
  { n: 5, base: 'thinking', what: 'readable, cut off at budget', reply: 'The sum of 2 and 2 is', done_reason: 'length', eval_count: 400, expect: true },
  { n: 6, base: 'text', what: 'empty, stop', reply: '', done_reason: 'stop', eval_count: 1, expect: false },
  { n: 7, base: 'vision', what: 'empty, whole budget thinking', reply: '', done_reason: 'length', eval_count: 400, expect: false },
  { n: 8, base: 'text', what: 'digit loop', reply: loop('4 '), done_reason: 'length', eval_count: 400, expect: false },
  { n: 9, base: 'thinking', what: 'word loop', reply: loop('the '), done_reason: 'length', eval_count: 400, expect: false },
  { n: 10, base: 'vision', what: 'leaked control token', reply: 'heart<channel|>heart', done_reason: 'stop', eval_count: 8, expect: false },
  { n: 11, base: 'text', what: 'chat-template leak', reply: '<start_of_turn>model<end_of_turn><eos>', done_reason: 'stop', eval_count: 5, expect: false },
  { n: 12, base: 'text', what: 'mojibake bytes', reply: 'Ã¤Ã¶Ã¼ï¿½ï¿½Ã\u0083Â©', done_reason: 'stop', eval_count: 12, expect: false },
  { n: 13, base: 'thinking', what: 'subword soup', reply: 'ation ingly ▁the ##s ▁▁ ##er ▁un', done_reason: 'stop', eval_count: 14, expect: false },
  { n: 14, base: 'text', what: 'whitespace and punctuation', reply: '\n\n . . .', done_reason: 'stop', eval_count: 6, expect: false },
  { n: 15, base: 'vision', what: 'refusal', reply: "I'm sorry, I can't see images.", done_reason: 'stop', eval_count: 9, expect: false },
];

// The step prints: jq -r '"<label>: " + reply[0:400]', jq -c envelope, then the marker.
const stdoutFor = (label: string, reply: string, done_reason: string, eval_count: number, marker: string) =>
  `${label}: ${reply.slice(0, 400)}\n${JSON.stringify({ error: null, done: true, done_reason, eval_count })}\n${marker}\n`;

const judge = new AgentJudge() as unknown as { buildPrompt(r: unknown): string };
const baseResult = (b: Base) => {
  const res = JSON.parse(readFileSync(`${artDir}/${b.id}.json`, 'utf8'));
  return { res, testCase: yaml.load(readFileSync(`${yamlDir}/${b.id}.yml`, 'utf8')), logs: readFileSync(`${artDir}/${b.id}.log`, 'utf8') };
};

// Self-check: the builder must reproduce each base step's real stdout byte for byte.
for (const [name, b] of Object.entries(BASES)) {
  const { res } = baseResult(b);
  const s = res.steps.find((x: { name: string }) => x.name === b.step);
  const [first, env, marker] = s.stdout.split(/\n(?=\{"error")|\n(?=[A-Z_]+_OK\n$)/);
  const reply = first.slice(b.label.length + 2);
  const e = JSON.parse(env);
  const rebuilt = stdoutFor(b.label, reply, e.done_reason, e.eval_count, marker.trim());
  console.log(`builder check ${name}: ${rebuilt === s.stdout ? 'exact' : 'MISMATCH'}`);
  if (rebuilt !== s.stdout) process.exit(1);
}

const prompts = CASES.map((c) => {
  const b = BASES[c.base];
  const { res, testCase, logs } = baseResult(b);
  const steps = res.steps.map((s: { name: string; stdout: string }) => {
    if (s.name !== b.step) return s;
    const marker = s.stdout.trim().split('\n').pop()!;
    return { ...s, stdout: stdoutFor(b.label, c.reply, c.done_reason, c.eval_count, marker) };
  });
  return judge.buildPrompt({ testCase, steps, logs, totalDuration: res.duration });
});

// ---- one agent process, a fresh session per judgement -----------------------------
const env = { ...process.env };
delete env.CLAUDECODE; delete env.CLAUDE_CODE_ENTRYPOINT; delete env.CLAUDE_CODE_SSE_PORT;
const child = spawn('../scripts/claude-ollama.sh --acp', { shell: true, stdio: ['pipe', 'pipe', 'ignore'], env });
let text = '';
const client: Client = {
  sessionUpdate: async (p) => { const u = p.update; if (u.sessionUpdate === 'agent_message_chunk' && u.content.type === 'text') text += u.content.text; },
  requestPermission: async (p) => { const r = p.options.find((o) => o.kind?.startsWith('reject')); return r ? { outcome: { outcome: 'selected', optionId: r.optionId } } : { outcome: { outcome: 'cancelled' } }; },
  readTextFile: async () => { throw new Error('off'); },
  writeTextFile: async () => { throw new Error('off'); },
};
const conn = new ClientSideConnection(() => client,
  ndJsonStream(Writable.toWeb(child.stdin!) as WritableStream<Uint8Array>, Readable.toWeb(child.stdout!) as ReadableStream<Uint8Array>));
await conn.initialize({ protocolVersion: PROTOCOL_VERSION, clientCapabilities: { fs: { readTextFile: false, writeTextFile: false }, terminal: false }, clientInfo: { name: 'judge-cases', version: '0' } });

async function judgeOnce(prompt: string, toolsOff: boolean) {
  const s = await conn.newSession({ cwd: process.cwd(), mcpServers: [], ...(toolsOff ? { _meta: { claudeCode: { options: { tools: [] } } } } : {}) });
  text = '';
  await conn.prompt({ sessionId: s.sessionId, prompt: [{ type: 'text', text: prompt }] });
  try { const j = JSON.parse(extractJson(text) ?? ''); return { pass: typeof j.pass === 'string' ? j.pass === 'true' : j.pass as boolean, reason: String(j.reason ?? '') }; }
  catch { return { pass: null, reason: `unparsed: ${text.slice(0, 80)}` }; }
}

await judgeOnce('Reply with exactly: ok', true); // warm the model

const out: Record<number, { off: unknown[]; on: unknown[] }> = {};
for (const c of CASES) out[c.n] = { off: [], on: [] };
for (let t = 0; t < TRIALS_OFF; t++) for (const [i, c] of CASES.entries()) {
  if (PICK && !PICK.includes(c.n)) continue;
  const v = await judgeOnce(prompts[i], true); out[c.n].off.push(v);
  console.log(`off t${t + 1} #${c.n} ${c.what}: ${v.pass === null ? 'UNPARSED' : v.pass ? 'PASS' : 'FAIL'} — ${v.reason.slice(0, 90)}`);
}
for (let t = 0; t < TRIALS_ON; t++) for (const [i, c] of CASES.entries()) {
  if (PICK && !PICK.includes(c.n)) continue;
  const v = await judgeOnce(prompts[i], false); out[c.n].on.push(v);
  console.log(`on  t${t + 1} #${c.n} ${c.what}: ${v.pass === null ? 'UNPARSED' : v.pass ? 'PASS' : 'FAIL'} — ${v.reason.slice(0, 90)}`);
}
writeFileSync(OUT, JSON.stringify({ cases: CASES, out }, null, 2));
child.kill('SIGKILL');
process.exit(0);

