D=~/.claude/projects/-tmp-claude-1000--home-jack-src-ollama37-a35b8673-ab88-4b7a-b50d-82d39aad564c-scratchpad-t-cicd-tests; python3 - "$D" <<'PY'
import json, glob, re, sys
D = sys.argv[1]
def thinkings(f):
    for line in open(f):
        try: r = json.loads(line)
        except: continue
        if r.get('type') == 'assistant':
            for b in r['message'].get('content', []):
                if b.get('type') == 'thinking' and b.get('thinking'): yield b['thinking']

WINDOW = 300   # chars of pure repetition before we call it a loop
def periodic(s, max_unit=200):
    for u in range(1, max_unit + 1):
        if all(s[i] == s[i % u] for i in range(len(s))): return s[:u]
    return None

def first_fire(text, step=20):
    # Simulate streaming: check the tail every `step` chars as chunks arrive.
    for p in range(WINDOW, len(text) + 1, step):
        unit = periodic(text[p - WINDOW:p])
        if unit is not None: return p, unit
    return None

loops, healthy = [], []
for f in glob.glob(D + '/*.jsonl'):
    for t in thinkings(f):
        (loops if re.search(r'(\b\S+\s)\1{50,}', t) else healthy).append(t)
for i, t in enumerate(loops):
    start = re.search(r'(\b\S+\s)\1{50,}', t).start()
    hit = first_fire(t)
    print(f"loop {i+1}: loop begins at char {start}; rule fires at char {hit[0]} (unit {hit[1]!r}), {hit[0]-start} chars in; generation that followed: {len(t)-hit[0]} chars")
fa = [first_fire(t) for t in healthy]
print(f"healthy blocks with a false alarm: {sum(x is not None for x in fa)} of {len(healthy)}")
for t, x in zip(healthy, fa):
    if x: print('   e.g.', repr(t[x[0]-80:x[0]]))
