#include <unistd.h>

typedef int (*set_fn)(int);
typedef int (*get_fn)(int *);
static FILE *out;
static pthread_mutex_t mu = PTHREAD_MUTEX_INITIALIZER;

int cudaSetDevice(int dev) {
    static set_fn real_set;
    static get_fn real_get;
    if (!real_set) {
        real_set = (set_fn)dlsym(RTLD_NEXT, "cudaSetDevice");
        real_get = (get_fn)dlsym(RTLD_NEXT, "cudaGetDevice");
    }
    int cur = -1;
    if (real_get) real_get(&cur);
    if (cur != dev) {
        pthread_mutex_lock(&mu);
